css:
.toggle-container {
  --step: 0.5s;
  --ease: linear(
    0 0%,
    0.2342 12.49%,
    0.4374 24.99%,
    0.6093 37.49%,
    0.6835 43.74%,
    0.7499 49.99%,
    0.8086 56.25%,
    0.8593 62.5%,
    0.9023 68.75%,
    0.9375 75%,
    0.9648 81.25%,
    0.9844 87.5%,
    0.9961 93.75%,
    1 100%
  );
  --offset: calc(var(--step) * 0.5);
  --bg-light: hsl(235 5% 85%);
  --bg-dark: #0b0e13;
  --button-light: hsl(223 4% 73%);
  --button-dark: hsl(220 27% 6%);
  --glow: hsl(182 90% 92%);
  width: 100%;
  height: 100%;
}

.scene {
  height: 100%;
  width: 100%;
  display: grid;
  place-items: center;
  background: var(--bg-dark);
  border-radius: 0px;
  position: relative;
  overflow: hidden;
  transition: background var(--step) var(--ease);
}
.scene::before {
  --size: 45px;
  --line: hsl(0 0% 100% / 0.07);
  content: "";
  height: 100%;
  width: 100%;
  position: absolute;
  background:
    linear-gradient(90deg, var(--line) 1px, transparent 1px var(--size)) 50% 50% /
      var(--size) var(--size),
    linear-gradient(var(--line) 1px, transparent 1px var(--size)) 50% 50% /
      var(--size) var(--size);
  mask: linear-gradient(-20deg, transparent 50%, white);
  pointer-events: none;
  transition: opacity var(--step) var(--ease);
}
.toggle-input {
  display: none;
}
.toggle-input:checked ~ .scene {
  background: var(--bg-light);
}
.toggle-input:checked ~ .scene::before {
  --line: hsl(0 0% 10% / 0.1);
}
.toggle {
  font-size: 64px;
  height: 2.3em;
  padding: 0;
  border-radius: 2.5em;
  border: 0;
  aspect-ratio: 1.8 / 1;
  position: relative;
  cursor: pointer;
  background: transparent;
  display: block;
}
.socket {
  position: absolute;
  inset: 0;
  border-radius: 3em;
  background: hsl(0 0% 0%);
  box-shadow: -0.05em 0.1em 0.2em -0.2em white;
  transition:
    background var(--step) var(--ease),
    box-shadow var(--step) var(--ease);
}
.socket-shadow {
  position: absolute;
  inset: 0;
  border-radius: inherit;
  box-shadow: 0em 0.075em 0.1em 0em white;
  opacity: 0;
  transition: opacity var(--step) var(--ease);
}
.face {
  position: absolute;
  inset: 0.15em;
  border-radius: 3em;
  scale: 1;
  transition: scale var(--step) var(--ease);
}
.face-plate {
  position: absolute;
  inset: 0;
  border-radius: inherit;
  box-shadow: -0.05em 0.1em 0.2em -0.2em white inset;
  background: conic-gradient(from 45deg, #0000, hsl(0 0% 100% / 0.05)),
    var(--button-dark);
  transition: background var(--step) var(--ease);
}
.face-shadow,
.face-shadow::after,
.face-shadow::before {
  position: absolute;
  inset: 0;
  border-radius: inherit;
}
.face-shadow::after,
.face-shadow::before {
  content: "";
}
.face-shadow::before {
  background: black;
}
.face-shadow::after {
  background: white;
  scale: 0.5;
  transition:
    opacity var(--step) var(--ease),
    translate var(--step) var(--ease),
    filter var(--step) var(--ease),
    scale var(--step) var(--ease);
}
.face-glowdrop {
  position: absolute;
  inset: 0;
  border-radius: inherit;
  scale: 0;
  transition: scale var(--step) var(--ease);
}
.face-glowdrop::after,
.face-glowdrop::before {
  content: "";
  height: 50%;
  aspect-ratio: 1;
  background: #fff;
  filter: blur(6px);
  position: absolute;
  z-index: -1;
  border-radius: 50%;
}
.face-glowdrop::before {
  left: 4%;
  width: 56%;
  translate: 0 -25%;
}
.face-glowdrop::after {
  bottom: 0;
  right: 12%;
  width: 34%;
  translate: 0 20%;
}
.face-glows {
  position: absolute;
  inset: -0.075em;
  opacity: 0;
  border-radius: inherit;
  mix-blend-mode: plus-lighter;
  filter: blur(8px);
  z-index: 20;
  mask: conic-gradient(from 280deg, #0000, #fff 20deg 45deg, #0000 95deg),
    conic-gradient(from 110deg, #0000, #fff 20deg, #0000 95deg);
  transition: opacity var(--step) var(--ease);
}
.face-glows div {
  position: absolute;
  inset: 0;
  border-radius: inherit;
  filter: blur(4px);
  border: 0.1em solid white;
}
.face-shine {
  position: absolute;
  inset: 0;
  opacity: 0;
  border-radius: 3em;
  transition: opacity var(--step) var(--ease);
}
.face-shine-shadow {
  position: absolute;
  inset: 0;
  border-radius: inherit;
  mask: conic-gradient(
    from 0deg,
    #fff 90deg,
    #0000 110deg 200deg,
    #fff 215deg 280deg,
    #0000 315deg
  );
  box-shadow:
    0.075em 0 0.025em -0.025em hsl(0 0% 0% / 0.5) inset,
    -0.075em -0.05em 0.025em -0.025em hsl(0 0% 0% / 0.5) inset;
}
.face-shine::before {
  content: "";
  position: absolute;
  inset: 0.05em;
  border-radius: 3em;
  box-shadow:
    0 -0.05em 0.025em -0.025em hsl(0 0% 50% / 0.5) inset,
    -0.025em 0.05em 0.025em -0.025em hsl(0 0% 100% / 0.5) inset;
}
.face-shine::after {
  content: "";
  position: absolute;
  inset: 0;
  background: conic-gradient(from 45deg, #0000, hsl(0 0% 100% / 0.25));
  border-radius: 3em;
}
.face svg {
  width: 25%;
  position: absolute;
  top: 50%;
  left: 50%;
  translate: -52% -48%;
  overflow: visible;
}
.face svg path {
  transform-box: fill-box;
  transform-origin: center center;
}
.svg-glow {
  z-index: 3;
  filter: drop-shadow(0 0 0.2em var(--glow));
  opacity: 1;
  transition: opacity var(--step) var(--ease);
}
.trail-holder {
  z-index: 2;
  filter: blur(10px);
}
.trail-holder .trail {
  stroke-width: 4;
}
.trail {
  stroke-dasharray: 10 80;
  stroke-dashoffset: 10;
  opacity: 0;
  transition:
    stroke-dashoffset calc(var(--step) * 3) var(--ease),
    opacity calc(var(--step) * 0.5) linear;
  transition-delay: var(--offset), calc(var(--offset) + calc(var(--step) * 2.5));
}
.inner-face {
  fill: hsl(230 5% 80%);
}
.glow-path {
  fill: var(--glow);
  stroke: var(--glow);
  opacity: 1;
  stroke-width: 0px;
}
.outline {
  stroke: black;
  transition: stroke var(--step) var(--ease);
}
.inner-bg {
  fill: black;
  transition: fill var(--step) var(--ease);
}

.toggle-input:checked ~ .scene .socket {
  background: hsl(0 0% 90%);
  box-shadow: -0.025em 0.08em 0.2em -0.1em white;
}
.toggle-input:checked ~ .scene .socket-shadow {
  opacity: 1;
}
.toggle-input:checked ~ .scene .face {
  scale: 1.12;
}
.toggle-input:checked ~ .scene .face-plate {
  background: conic-gradient(from 45deg, #0000, hsl(0 0% 100% / 0.05)),
    var(--button-light);
}
.toggle-input:checked ~ .scene .face-glowdrop {
  scale: 1;
}
.toggle-input:checked ~ .scene .face-glows {
  opacity: 1;
}
.toggle-input:checked ~ .scene .face-shine {
  opacity: 1;
}
.toggle-input:checked ~ .scene .face-shadow::before {
  translate: -15% 55%;
  filter: blur(1em);
  opacity: 0.35;
}
.toggle-input:checked ~ .scene .face-shadow::after {
  filter: blur(0.5em);
  scale: 1;
}
.toggle-input:checked ~ .scene .svg-glow {
  opacity: 0;
  transition-duration: var(--step);
  transition-delay: 0s;
}
.toggle-input:checked ~ .scene .outline {
  stroke: hsl(0 0% 30%);
}
.toggle-input:checked ~ .scene .inner-bg {
  fill: hsl(0 0% 20%);
}
.toggle-input:checked ~ .scene .trail {
  stroke-dashoffset: -70;
  opacity: 1;
  transition: stroke-dashoffset 0s;
}
.label-text {
  position: absolute;
  bottom: 1.2rem;
  font-size: 13px;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  color: hsl(0 0% 50%);
  font-family: system-ui, sans-serif;
  transition: color var(--step) var(--ease);
  user-select: none;
  pointer-events: none;
}
.toggle-input:checked ~ .scene .label-text {
  color: hsl(0 0% 40%);
}
.toggle:active .face {
  scale: 0.99;
}
.toggle:active .socket {
  box-shadow: -0.045em 0.1em 0.2em -0.15em white;
}
